// Locally bundled demo photos (illustrations generated by scripts/demo-scenes.mjs). No external hosts,
// no real people: each scene shows a person from behind in a place.
import beach from "./assets/scenes/beach.svg";
import cafe from "./assets/scenes/cafe.svg";
import cityDusk from "./assets/scenes/city-dusk.svg";
import jazzBar from "./assets/scenes/jazz-bar.svg";
import market from "./assets/scenes/market.svg";
import mountains from "./assets/scenes/mountains.svg";
import museum from "./assets/scenes/museum.svg";
import park from "./assets/scenes/park.svg";

export const SCENES = { beach, cafe, "city-dusk": cityDusk, "jazz-bar": jazzBar, market, mountains, museum, park };

/** Photo URLs for a person, in profile order. */
export const photosOf = (person) => (person.photos ?? []).map((key) => SCENES[key]).filter(Boolean);
